INSERT INTO gold_texts (gold, lang, title, text) VALUES
  ('nematodes-46000', 'de', 'Die Würmer, die 46.000 Jahre verschlafen haben', 'Etwa 40 Meter unter der Oberfläche am Fluss Kolyma in Sibirien fanden Forschende einen fossilen Nagetierbau und darin winzige Fadenwürmer. Die Radiokarbondatierung von Pflanzenresten aus dem Bau ergab rund 46.000 Jahre. Nach dem Auftauen wurden die Würmer wieder lebendig und entpuppten sich als neue Art: Panagrolaimus kolymaensis. Sie vermehren sich ohne Männchen und teilen Überlebenstricks mit einem berühmten Laborwurm. Die Studie erschien 2023 in PLOS Genetics. Ganz überzeugt sind nicht alle: Manche Fachleute sagen, die Datierung beweise das Alter der Erde, aber nicht unbedingt das der Würmer.'),
  ('nematodes-46000', 'en', 'The Worms That Slept Through 46,000 Years', 'About 40 meters below the surface at the Kolyma River in Siberia, researchers found a fossil rodent burrow, and in it microscopic roundworms. Radiocarbon dating of plant material from the burrow came out at about 46,000 years. After thawing, the worms came back to life and turned out to be a new species: Panagrolaimus kolymaensis. They reproduce without males and share survival tricks with a famous lab worm. The study appeared in PLOS Genetics in 2023. Not everyone is convinced: some biologists say the dating proves the age of the soil, not necessarily of the worms.');
INSERT INTO gold_sources (gold, pos, label, url) VALUES
  ('nematodes-46000', 1, 'PLOS Genetics: A novel nematode species from the Siberian permafrost shares adaptive mechanisms for cryptobiotic survival with C. elegans dauer larva', 'https://journals.plos.org/plosgenetics/article?id=10.1371%2Fjournal.pgen.1010798'),
  ('nematodes-46000', 2, 'Scientific American: 46,000-Year-Old Worm Possibly Revived from Siberian Permafrost', 'https://www.scientificamerican.com/article/46-000-year-old-worm-possibly-revived-from-siberian-permafrost/');
